@icontract.snapshot(lambda self: self.plugins[:], name='plugins')
@icontract.snapshot(lambda self: [hasattr(p, 'close') for p in self.plugins], name='had_close')
@icontract.snapshot(lambda self: [getattr(p, 'name', True) for p in self.plugins], name='names')
@icontract.ensure(lambda result, OLD, self, plugin:
    result == [OLD.plugins[i] for i in range(len(OLD.plugins)-1, -1, -1)
               if (plugin is True)
               or (plugin is OLD.plugins[i])
               or (plugin is type(OLD.plugins[i]))
               or (OLD.names[i] == plugin)])
@icontract.ensure(lambda OLD, self, plugin:
    self.plugins == [p for p in OLD.plugins
                     if p not in [OLD.plugins[i] for i in range(len(OLD.plugins)-1, -1, -1)
                                  if (plugin is True)
                                  or (plugin is OLD.plugins[i])
                                  or (plugin is type(OLD.plugins[i]))
                                  or (OLD.names[i] == plugin)]])
@icontract.ensure(lambda OLD, result:
    all((not OLD.had_close[i]) or (OLD.plugins[i] not in result) or getattr(OLD.plugins[i], 'closed', False)
        for i in range(len(OLD.plugins))))
